/**
 * Compiles the documentation content into a single generated TypeScript module.
 *
 * Inputs:
 *  - `docs-content/guides/*.md`      hand-written, checked-in guide pages
 *  - `docs-content/nav.json`         checked-in sidebar manifest (optional:
 *                                    falls back to alphabetical guides)
 *  - `docs-content/api/`            TypeDoc output (typedoc-plugin-markdown),
 *                                    regenerated by `npm run docs:typedoc`
 *
 * Output: `src/docs/generated/content.ts` — pages (slug → title, HTML) plus the
 * sidebar structure. HTML is fully pre-rendered here: heading anchors are
 * slugified, code fences are highlighted with highlight.js, and relative
 * markdown links are rewritten to the site's hash routes
 * (`#/docs/<slug>[?to=<anchor>]`), so the app only renders static strings.
 *
 * Any unresolved relative link or empty content set fails the build loudly:
 * generation errors must never deploy empty documentation.
 */
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Marked } from 'marked';
import hljs from 'highlight.js/lib/core';
import typescript from 'highlight.js/lib/languages/typescript';
import javascript from 'highlight.js/lib/languages/javascript';
import bash from 'highlight.js/lib/languages/bash';
import json from 'highlight.js/lib/languages/json';
import plaintext from 'highlight.js/lib/languages/plaintext';

const siteRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const contentDir = path.join(siteRoot, 'docs-content');
const guidesDir = path.join(contentDir, 'guides');
const apiDir = path.join(contentDir, 'api');
const outPath = path.join(siteRoot, 'src', 'docs', 'generated', 'content.ts');

const VERIFY = process.argv.includes('--verify');

hljs.registerLanguage('typescript', typescript);
hljs.registerLanguage('javascript', javascript);
hljs.registerLanguage('bash', bash);
hljs.registerLanguage('shell', bash);
hljs.registerLanguage('sh', bash);
hljs.registerLanguage('json', json);
hljs.registerLanguage('plaintext', plaintext);
hljs.registerLanguage('text', plaintext);

/** Repository-relative path from an absolute one, for error messages. */
function rel(absolute) {
    return path.relative(siteRoot, absolute);
}

function slugifyHeading(text) {
    const slug = text
        .toLowerCase()
        .replace(/<[^>]+>/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
    return slug === '' ? 'section' : slug;
}

/** Nav label for a TypeDoc page title like "Class: Shape" → "Shape". */
function apiNavTitle(firstHeading) {
    return firstHeading.replace(/^#+\s*/, '').replace(/^[A-Za-z ]+:\s*/, '').replace(/\(\)$/, '').trim();
}

async function readIfExists(filePath) {
    try {
        return await readFile(filePath, 'utf8');
    } catch {
        return null;
    }
}

async function listFiles(rootDir) {
    const entries = await readdir(rootDir, { recursive: true, withFileTypes: true });
    return entries
        .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
        .map((entry) => path.relative(rootDir, path.join(entry.parentPath ?? entry.path, entry.name)));
}

function firstHeading(markdown) {
    const match = /^#\s+(.+)$/m.exec(markdown);
    return match?.[1]?.trim() ?? '';
}

function prettyGuideName(slug) {
    return slug
        .split('-')
        .map((word) => (word === '' ? word : word[0].toUpperCase() + word.slice(1)))
        .join(' ');
}

// --------------------------------------------------------------------------
// Link rewriting: markdown-relative hrefs → site hash routes.

function createLinkRewriter({ currentSlug, slugBySource }) {
    return (html, sourcePath) => {
        const sourceDir = path.dirname(sourcePath);
        return html.replace(/href="([^"]*)"/g, (whole, href) => {
            if (/^(https?:|mailto:|#)/.test(href)) {
                if (href.startsWith('#')) {
                    const anchor = href.slice(1);
                    return `href="#/docs/${currentSlug}?to=${anchor}"`;
                }
                return whole;
            }
            const match = /^(.+?\.md)(#[^"]*)?$/.exec(href);
            if (!match) return whole; // asset or hash-less external link
            const targetAbs = path.resolve(sourceDir, match[1]);
            const targetKey = path.relative(contentDir, targetAbs);
            const slug = slugBySource.get(targetKey);
            if (slug === undefined) {
                throw new Error(
                    `${rel(sourcePath)} links to "${href}" but no docs page exists for ${targetKey}`,
                );
            }
            const anchor = match[2]?.slice(1);
            return anchor
                ? `href="#/docs/${slug}?to=${anchor}"`
                : `href="#/docs/${slug}"`;
        });
    };
}

// --------------------------------------------------------------------------
// Markdown rendering with heading anchors and code highlighting.

function createMarkdownRenderer(rewriteLinks) {
    const anchorCounts = new Map();
    const marked = new Marked();
    marked.use({
        renderer: {
            heading({ tokens, depth }) {
                const inner = this.parser.parseInline(tokens);
                const base = slugifyHeading(inner.replace(/<[^>]+>/g, ''));
                const count = anchorCounts.get(base) ?? 0;
                anchorCounts.set(base, count + 1);
                const id = count === 0 ? base : `${base}-${count}`;
                return `<h${depth} id="${id}">${inner}</h${depth}>\n`;
            },
            code({ text, lang }) {
                const language = (lang ?? '').split(/\s+/)[0] ?? '';
                const hljsLanguage =
                    language === 'ts' ? 'typescript' :
                    language === 'js' ? 'javascript' :
                    language === '' ? 'plaintext' : language;
                const body = hljsLanguage && hljs.getLanguage(hljsLanguage)
                    ? hljs.highlight(text, { language: hljsLanguage }).value
                    : hljs.highlight(text, { language: 'plaintext' }).value;
                const shown = language === '' ? '' : ` class="language-${language}"`;
                return `<pre><code${shown}>${body}</code></pre>\n`;
            },
        },
    });
    return async (markdown, sourcePath) => rewriteLinks(await marked.parse(markdown), sourcePath);
}

// --------------------------------------------------------------------------
// Content assembly.

async function buildGuides() {
    const navRaw = await readIfExists(path.join(contentDir, 'nav.json'));
    let files = [];
    try {
        files = (await readdir(guidesDir)).filter((name) => name.endsWith('.md')).sort();
    } catch (error) {
        if (navRaw !== null) {
            throw new Error(`nav.json exists but guides/ is unreadable: ${error.message}`);
        }
        return { pages: [], sections: [], slugBySource: new Map() };
    }
    if (files.length === 0 && navRaw === null) {
        return { pages: [], sections: [], slugBySource: new Map() };
    }

    const pages = [];
    const slugBySource = new Map();
    const titleBySlug = new Map();
    for (const name of files) {
        const slug = name.replace(/\.md$/, '');
        const source = path.join(guidesDir, name);
        const markdown = await readFile(source, 'utf8');
        titleBySlug.set(slug, firstHeading(markdown) || prettyGuideName(slug));
        slugBySource.set(path.join('guides', name), slug);
        pages.push({ slug, title: '', markdown, source });
    }

    let sections;
    if (navRaw !== null) {
        const nav = JSON.parse(navRaw);
        const listed = new Set();
        sections = nav.sections.map((section) => {
            const entries = section.pages.map((slug) => {
                if (!titleBySlug.has(slug)) {
                    throw new Error(`nav.json lists "${slug}" but guides/${slug}.md does not exist`);
                }
                listed.add(slug);
                return { slug, title: titleBySlug.get(slug) };
            });
            return { id: section.id, label: section.label, entries };
        });
        for (const slug of titleBySlug.keys()) {
            if (!listed.has(slug)) {
                throw new Error(`guides/${slug}.md exists but is not listed in nav.json`);
            }
        }
    } else {
        sections = [{
            id: 'guides',
            label: 'Guides',
            entries: files.map((name) => {
                const slug = name.replace(/\.md$/, '');
                return { slug, title: titleBySlug.get(slug) };
            }),
        }];
    }
    return { pages, sections, slugBySource };
}

const API_KIND_LABELS = {
    classes: 'API · Classes',
    functions: 'API · Functions',
    interfaces: 'API · Interfaces',
    'type-aliases': 'API · Type aliases',
};
const API_KIND_ORDER = Object.keys(API_KIND_LABELS);

async function buildApi() {
    let files = [];
    try {
        files = await listFiles(apiDir);
    } catch {
        return { pages: [], sections: [], slugBySource: new Map() };
    }
    if (files.length === 0) return { pages: [], sections: [], slugBySource: new Map() };
    files.sort();

    const pages = [];
    const slugBySource = new Map();
    const entriesByKind = new Map();
    for (const name of files) {
        const posix = name.split(path.sep).join('/');
        const isIndex = posix === 'index.md';
        const kind = path.posix.dirname(posix);
        const slug = isIndex ? 'api' : `api/${posix.replace(/\.md$/, '').toLowerCase()}`;
        const source = path.join(apiDir, name);
        const markdown = await readFile(source, 'utf8');
        const heading = firstHeading(markdown);
        const title = isIndex
            ? 'API reference'
            : apiNavTitle(heading) || prettyGuideName(path.basename(name, '.md'));
        slugBySource.set(path.join('api', name), slug);
        if (!isIndex) {
            const list = entriesByKind.get(kind) ?? [];
            list.push({ slug, title });
            entriesByKind.set(kind, list);
        }
        pages.push({ slug, title, markdown, source });
    }

    const sections = [{
        id: 'api',
        label: 'API reference',
        entries: [{ slug: 'api', title: 'API reference' }],
    }];
    for (const kind of API_KIND_ORDER) {
        const entries = entriesByKind.get(kind);
        if (entries?.length) {
            entries.sort((a, b) => a.title.localeCompare(b.title));
            sections.push({ id: `api-${kind}`, label: API_KIND_LABELS[kind], entries });
        }
    }
    return { pages, sections, slugBySource };
}

// --------------------------------------------------------------------------

function formatTitle(name) {
    const title = firstHeading(name);
    return title !== '' ? title : prettyGuideName(path.basename(name, '.md'));
}

async function main() {
    const guides = await buildGuides();
    const api = await buildApi();

    const slugBySource = new Map([...guides.slugBySource, ...api.slugBySource]);
    for (const { pages } of [guides, api]) {
        for (const page of pages) {
            if (page.title === '') page.title = formatTitle(page.markdown);
        }
    }

    const compiled = [];
    for (const page of [...guides.pages, ...api.pages]) {
        const rewriter = createLinkRewriter({ currentSlug: page.slug, slugBySource });
        const markdownRenderer = createMarkdownRenderer(rewriter);
        const html = await markdownRenderer(page.markdown, page.source);
        compiled.push({ slug: page.slug, title: page.title, html });
    }

    const sections = [...guides.sections, ...api.sections];
    if (compiled.length === 0) {
        throw new Error('no documentation content found; run `npm run docs:typedoc` first');
    }
    if (VERIFY) {
        const slugs = new Set(compiled.map((page) => page.slug));
        for (const section of sections) {
            for (const entry of section.entries) {
                if (!slugs.has(entry.slug)) {
                    throw new Error(`nav entry "${entry.slug}" has no compiled page`);
                }
            }
        }
        if (!slugs.has('api')) throw new Error('the generated API reference landing page is missing');
        const guideCount = compiled.filter((page) => !page.slug.startsWith('api/')).length;
        if (guideCount < 2) throw new Error('expected at least two guide pages');
        console.log(`docs:check OK — ${compiled.length} pages, ${sections.length} nav sections`);
    }

    const lines = [];
    lines.push('/* eslint-disable */');
    lines.push('/**');
    lines.push(' * Generated by `scripts/build-docs.mjs` — do not edit.');
    lines.push(' * Sources: `docs-content/guides/*.md` (checked in) and');
    lines.push(' * `docs-content/api/**` (TypeDoc via typedoc-plugin-markdown).');
    lines.push(' */');
    lines.push('');
    lines.push('export interface DocsPage {');
    lines.push('    slug: string;');
    lines.push('    title: string;');
    lines.push('    html: string;');
    lines.push('}');
    lines.push('');
    lines.push('export interface DocsNavEntry {');
    lines.push('    slug: string;');
    lines.push('    title: string;');
    lines.push('}');
    lines.push('');
    lines.push('export interface DocsNavSection {');
    lines.push('    id: string;');
    lines.push('    label: string;');
    lines.push('    entries: readonly DocsNavEntry[];');
    lines.push('}');
    lines.push('');
    lines.push(`export const docsPages: readonly DocsPage[] = ${JSON.stringify(compiled, null, 4)};`);
    lines.push('');
    lines.push(`export const docsNav: readonly DocsNavSection[] = ${JSON.stringify(sections, null, 4)};`);
    lines.push('');

    await mkdir(path.dirname(outPath), { recursive: true });
    await writeFile(outPath, lines.join('\n'), 'utf8');
    console.log(`docs: wrote ${compiled.length} pages → ${rel(outPath)}`);
}

main().catch((error) => {
    console.error(`docs build failed: ${error.message}`);
    process.exit(1);
});
